"""LLM client — thin wrapper over llm_factory for engine turns.

``LLMClient`` is the single LLM access point for the Orchestrator.
It is stateless: construct one per turn from ``ModelBootstrap``.

Usage::

    client = LLMClient.from_bootstrap(bootstrap)
    response = await client.acompletion(messages, tools=tool_list)  # sync: completion()
    # or, when the channel streams tokens:
    # response = await client.acompletion_streaming(
    #     messages, output_channel, recipient_id, tools=tool_list
    # )
    if response.response_text():
        # plain text — end of turn
    for tc in response.tool_calls or []:
        # dispatch tc.tool_name with tc.arguments
"""

from __future__ import annotations

from typing import TYPE_CHECKING, Any, Dict, List, Mapping, Optional, Union

import structlog

from rasa.agents.schemas.agent_tool_schema import AgentToolSchema
from rasa.exceptions import ValidationError
from rasa.mantle.model_archive.bootstrap import ModelBootstrap
from rasa.mantle.prompts.messages import LlmMessage
from rasa.mantle.prompts.token_budget import PROMPT_ONLY_LLM_CONFIG_KEYS
from rasa.shared.constants import MODELS_CONFIG_KEY
from rasa.shared.exceptions import InvalidConfigException
from rasa.shared.providers.llm.llm_client import LLMClient as _ProviderClient
from rasa.shared.providers.llm.llm_response import LLMResponse, measure_llm_latency
from rasa.shared.providers.model_group_validation import (
    validate_model_group_credentials,
)
from rasa.shared.utils.llm import acompletion_with_streaming, llm_factory

if TYPE_CHECKING:
    from rasa.core.channels.channel import OutputChannel

structlogger = structlog.get_logger()

_DEFAULT_LLM_CONFIG: Dict[str, Any] = {}

# Provider-supported, non-secret per-call overrides that hooks may set via
# ``ModelRequestPayload.model_settings``. Credentials, provider/model, and tools
# stay engine-owned and must never appear here.
ALLOWED_PER_CALL_MODEL_SETTINGS: frozenset[str] = frozenset(
    {
        "temperature",
        "top_p",
        "max_tokens",
        "presence_penalty",
        "frequency_penalty",
        "stop",
        "seed",
    }
)

_FLOAT_MODEL_SETTINGS = frozenset(
    {"temperature", "top_p", "presence_penalty", "frequency_penalty"}
)
_INT_MODEL_SETTINGS = frozenset({"max_tokens", "seed"})


def _is_valid_per_call_setting_value(key: str, value: Any) -> bool:
    """Return whether *value* has a provider-safe type for allowlisted *key*."""
    if key in _FLOAT_MODEL_SETTINGS:
        return isinstance(value, (int, float)) and not isinstance(value, bool)
    if key in _INT_MODEL_SETTINGS:
        return isinstance(value, int) and not isinstance(value, bool)
    if key == "stop":
        if isinstance(value, str):
            return True
        if isinstance(value, list):
            return all(isinstance(item, str) for item in value)
        return False
    return False


def filter_per_call_model_settings(
    settings: Optional[Mapping[str, Any]],
) -> Dict[str, Any]:
    """Return allowlisted per-call model settings with provider-safe value types.

    Unknown keys are dropped. Allowlisted keys with unexpected value types
    (for example a dict ``temperature`` or non-string ``stop`` entries) are
    also dropped so a buggy hook cannot force provider-invalid kwargs.
    """
    if not settings:
        return {}
    filtered: Dict[str, Any] = {}
    for key, value in settings.items():
        if key not in ALLOWED_PER_CALL_MODEL_SETTINGS:
            continue
        if not _is_valid_per_call_setting_value(key, value):
            structlogger.warning(
                "mantle.llm.model_settings.invalid_value",
                key=key,
                value_type=type(value).__name__,
            )
            continue
        filtered[key] = value
    return filtered


def _completion_kwargs(
    tools: Optional[List[Dict[str, Any]]],
    model_settings: Optional[Mapping[str, Any]],
) -> Dict[str, Any]:
    """Build provider kwargs for a completion call."""
    kwargs: Dict[str, Any] = {}
    if tools:
        kwargs["tools"] = tools
    kwargs.update(filter_per_call_model_settings(model_settings))
    return kwargs


def resolve_llm_model_name(llm_config: Mapping[str, Any]) -> str:
    """Return the first model name from a resolved model group.

    The first configured model provides a stable tokenizer and request label
    when a router can select from multiple models. Azure groups may identify
    that model through ``deployment`` instead of ``model``.
    """
    models = llm_config.get("models")
    if isinstance(models, list) and models:
        first = models[0]
        if isinstance(first, Mapping):
            nested = first.get("model") or first.get("deployment")
            if nested:
                return str(nested)
    return ""


def _format_messages_for_log(messages: List[LlmMessage]) -> str:
    """Render the message list as a readable transcript for debug logging.

    Produces one block per message — ``[role] <content>``, with tool calls
    shown as ``-> name(args)`` and tool-result messages tagged by their
    ``tool_call_id`` — so the full prompt can be read top-to-bottom in logs.
    """
    blocks: List[str] = []
    for message in messages:
        role = message.get("role", "?")
        tool_call_id = message.get("tool_call_id")
        header = (
            f"[{role} tool_call_id={tool_call_id}]" if tool_call_id else f"[{role}]"
        )

        content = message.get("content")
        if content:
            blocks.append(f"{header}\n{content}")

        for tool_call in message.get("tool_calls") or []:
            function = tool_call.get("function", {})
            blocks.append(
                f"{header} -> {function.get('name')}({function.get('arguments')})"
            )

        if not content and not message.get("tool_calls"):
            blocks.append(f"{header} <empty>")
    return "\n\n".join(blocks)


def tool_schema_name(tool: Union[AgentToolSchema, Mapping[str, Any]]) -> Optional[str]:
    """Extract a tool name from an ``AgentToolSchema`` or OpenAI-format schema dict."""
    if isinstance(tool, AgentToolSchema):
        return tool.name
    function = tool.get("function") or {}
    return function.get("name") or tool.get("name")


def tool_schema_names(
    tools: Optional[List[Union[AgentToolSchema, Mapping[str, Any]]]],
) -> List[str]:
    """Extract tool names from schemas (skips entries without a name)."""
    return [
        name for tool in tools or [] if (name := tool_schema_name(tool)) is not None
    ]


def _log_llm_request(
    messages: List[LlmMessage],
    tools: Optional[List[Dict[str, Any]]],
) -> None:
    """Emit the shared ``mantle.llm.request`` debug event with the prompt."""
    structlogger.debug(
        "mantle.llm.request",
        message_count=len(messages),
        tool_count=len(tools) if tools else 0,
        tool_names=tool_schema_names(tools),
        prompt=_format_messages_for_log(messages),
    )


def _log_llm_response(response: LLMResponse) -> None:
    """Emit the shared ``mantle.llm.response`` debug event."""
    tool_calls = response.tool_calls or []
    structlogger.debug(
        "mantle.llm.response",
        has_text=bool(response.response_text()),
        tool_call_count=len(tool_calls),
        response_text=response.response_text(),
        tool_names=[tc.tool_name for tc in tool_calls],
        tool_calls=[{"name": tc.tool_name, "args": tc.tool_args} for tc in tool_calls],
        highlight=True,
    )


class LLMClient:
    """LLM wrapper for one engine turn or sync packaging call.

    Constructed per turn from ``ModelBootstrap.llm``; stateless between
    calls so it is safe to construct fresh on every ``run_turn`` invocation.
    Use :meth:`acompletion` on async paths and :meth:`completion` on sync paths.
    """

    def __init__(self, llm_client: _ProviderClient) -> None:
        self._client = llm_client

    # ------------------------------------------------------------------
    # Construction
    # ------------------------------------------------------------------

    @classmethod
    def from_bootstrap(cls, bootstrap: ModelBootstrap) -> "LLMClient":
        """Build a client from the resolved orchestrator model group.

        Model-group credentials use ``api_key`` environment references.
        """
        llm_config = dict(bootstrap.llm)
        # Prompt-construction knobs (e.g. max_prompt_tokens) are not provider
        # settings — strip them before the config reaches llm_factory.
        for prompt_only_key in PROMPT_ONLY_LLM_CONFIG_KEYS:
            llm_config.pop(prompt_only_key, None)
        if MODELS_CONFIG_KEY in llm_config:
            try:
                validate_model_group_credentials([llm_config])
            except ValidationError as error:
                raise InvalidConfigException(
                    "The orchestrator model group has invalid credentials: "
                    f"{error.info or error}"
                ) from error
        client = llm_factory(llm_config, _DEFAULT_LLM_CONFIG)
        return cls(client)

    # ------------------------------------------------------------------
    # Completion
    # ------------------------------------------------------------------

    def completion(
        self,
        messages: List[LlmMessage],
        tools: Optional[List[Dict[str, Any]]] = None,
        model_settings: Optional[Mapping[str, Any]] = None,
    ) -> LLMResponse:
        """Synchronously call the LLM and return the full response.

        Mirrors :meth:`acompletion` for packaging and other sync call sites
        that must not spin up an event loop via ``asyncio.run``.

        Args:
            messages: Ordered LLM message list (system, history, current user).
            tools: Optional list of OpenAI-format tool schemas to expose.
            model_settings: Optional allowlisted per-call overrides (for example
                ``temperature``, ``top_p``, ``max_tokens``). Unknown or secret
                keys are ignored.

        Returns:
            ``LLMResponse`` with ``choices`` (text) and ``tool_calls``.
        """
        kwargs = _completion_kwargs(tools, model_settings)

        _log_llm_request(messages, tools)

        raw = self._client.completion(messages, **kwargs)
        response = LLMResponse.ensure_llm_response(raw)
        _log_llm_response(response)
        return response

    @measure_llm_latency
    async def acompletion(
        self,
        messages: List[LlmMessage],
        tools: Optional[List[Dict[str, Any]]] = None,
        model_settings: Optional[Mapping[str, Any]] = None,
    ) -> LLMResponse:
        """Call the LLM and return the full response.

        Args:
            messages: Ordered LLM message list (system, history, current user).
            tools: Optional list of OpenAI-format tool schemas to expose.
            model_settings: Optional allowlisted per-call overrides (for example
                ``temperature``, ``top_p``, ``max_tokens``). Unknown or secret
                keys are ignored.

        Returns:
            ``LLMResponse`` with ``choices`` (text) and ``tool_calls``.
        """
        kwargs = _completion_kwargs(tools, model_settings)

        _log_llm_request(messages, tools)

        raw = await self._client.acompletion(messages, **kwargs)
        response = LLMResponse.ensure_llm_response(raw)
        _log_llm_response(response)
        return response

    async def acompletion_streaming(
        self,
        messages: List[LlmMessage],
        output_channel: "OutputChannel",
        recipient_id: str,
        tools: Optional[List[Dict[str, Any]]] = None,
        model_settings: Optional[Mapping[str, Any]] = None,
        response_event_id: Optional[str] = None,
    ) -> LLMResponse:
        """Stream the LLM completion and return the assembled response.

        Emits the same ``mantle.llm.request`` / ``mantle.llm.response``
        debug events as :meth:`acompletion`, so prompt visibility does not
        depend on whether the output channel streams tokens.

        Args:
            messages: Ordered LLM message list (system, history, current user).
            output_channel: Channel that receives streamed token chunks.
            recipient_id: Recipient ID for the output channel.
            response_event_id: Event id of the ``BotUttered`` this text becomes;
                voice playback markers carry it.
            tools: Optional list of OpenAI-format tool schemas to expose.
            model_settings: Optional allowlisted per-call overrides (for example
                ``temperature``, ``top_p``, ``max_tokens``). Unknown or secret
                keys are ignored.

        Returns:
            ``LLMResponse`` with ``choices`` (text) and ``tool_calls``.
        """
        kwargs = _completion_kwargs(tools, model_settings)

        _log_llm_request(messages, tools)

        response = await acompletion_with_streaming(
            self._client,
            messages,
            output_channel,
            recipient_id,
            response_event_id=response_event_id,
            **kwargs,
        )
        response = LLMResponse.ensure_llm_response(response)
        _log_llm_response(response)
        return response
